def fill_enclosed(grid, line, fill=4):
    """Cells of a color not the boundary line that are unreachable from the border become fill."""
    h,w=len(grid),len(grid[0])
    g=[row[:] for row in grid]
    seen=set()
    from collections import deque
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]!=line: q.append((i,j)); seen.add((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]!=line: q.append((i,j)); seen.add((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]!=line:
                seen.add((a,b)); q.append((a,b))
    return [[fill if (i,j) not in seen else g[i][j] for j,v in enumerate(row)] for i,row in enumerate(g)]

